    number,
    { remaining: 0 | 1; lastDecision: { day: number; activate: boolean } | null }
  >;
  cats: Set<number>;
  beauty: Map<number, AnimalBeautyKnowledge>;
  bear: Array<{ day: number; roared: boolean }>;
