  world: World,
  id: number,
  living = true,
): AnimalOriginalPlayer | null {
  if (!animalRosterCurrent(world)) return null;
  const p = rosters.get(world)!.players.get(id);
  return p && current(world, p, living) ? p : null;
}
/** 可返回首次死亡的原体；caller 行动仍需存活 lease。 */
